import{z as i,x as s,o as t,c as p,q as B,j as r,D as e,d as l,s as o,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"投机与量化的组合","description":"","frontmatter":{"title":"投机与量化的组合","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/spec-quant-combo.md","filePath":"llm/spec-quant-combo.md","lastUpdated":1791413859000}'),d={name:"llm/spec-quant-combo.md"};function m(C,a,f,h,D,u){const n=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=B('<h1 id="投机与量化的组合" tabindex="-1">投机与量化的组合 <a class="header-anchor" href="#投机与量化的组合" aria-label="Permalink to &quot;投机与量化的组合&quot;">​</a></h1><div class="epigraph"><p>两个杠杆都从「每 token 搬多少字节」里找钱，装在同一台机器上时，它们既相乘，又互相抢同一份余量。</p><footer>—— 据 Leviathan et al., 2023 与本仓库量化、投机两课序的综合口径整理</footer></div><p><a href="/llm/spec-mtp-training">上一课</a>把 \\(\\alpha\\) 训了上去。生产栈里还有一个躲不开的队友：量化。目标权重与 KV 常年活在 <a href="/llm/fp8-inference">fp8</a> 或 <a href="/llm/kv-quant-int8-int4">int8/int4 KV</a> 下，草稿往往压得更狠。本课写两者组合时的三笔账：无损相对谁成立、草稿能压多狠、以及量化怎么动投机赖以赚钱的那份带宽余量。量化本身的误差评估见<a href="/llm/quant-eval-degradation">量化评测退化</a>，不重讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>第一个坑是「无损」的参照系。投机声明无损时，参照的是<strong>部署中的目标模型</strong>：量化目标加全精度草稿，无损是相对量化后那个 \\(p\\) 成立的；拿 bf16 目标的加速比数字搬到量化部署上，中间差着一份量化退化。第二个坑是接受率漂移：草稿在 bf16 目标上训练校准，部署到量化目标上，\\(p\\) 整体动了——量化噪声把分布摊平，\\(\\alpha\\) 相对训练值下滑，下滑多少没人替你测就得自己测。第三个坑最隐蔽：两者抢余量。<a href="/llm/spec-batching-interaction">投机与批处理的交互</a>钉过，投机在校验近免费时赚得最多，而「近免费」的前提是 decode 卡在带宽墙；量化恰好把每步要搬的字节砍半，算术强度翻倍，校验前向可能先一步离开带宽墙——量化越激进，投机赖以赚钱的余量越小。</p><p><span class="marginnote">直觉类比：量化后的目标模型像一张翻录过的唱片。投机声明「无损」，意思是输出与这张翻录唱片完全一致——它从不担保与原始母带（bf16 原模型）逐比特相同。所以「无损」必须带上参照系才有意义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>在部署对上测</strong>。接受率与加速比一律在「部署的量化目标 + 部署的草稿」这一对上重测，bf16 表只当历史参考。<strong>草稿压狠、目标压稳</strong>。草稿的错误只花接受率不花正确性——无损由接受规则对部署的 \\(p\\) 兑现，草稿量化误差的代价全部记在 \\(\\alpha\\) 上。于是灵敏度不对称：目标量化按<a href="/llm/quant-eval-degradation">量化评测退化</a>的质量线走，草稿量化按 \\(\\alpha\\) 曲线走，后者宽容得多，W4/W8 草稿配 fp8 目标是常见档位。<strong>KV 与校验</strong>。校验前向读的是 \\(\\gamma+1\\) 个位置的 KV，<a href="/llm/kv-quant-int8-int4">KV 量化</a>把这笔带宽同步砍半；量化注意力的内核路径见<a href="/llm/ak-quantized-attention-kernel">量化注意力内核</a>，形状仍是「短而宽」，别退化成逐 token 调用。<strong>联评</strong>。成本比 \\(c_q/c_p\\) 在两个量化档下都变了，\\(\\gamma\\) 与树宽的重调以实测为准，不搬全精度表。</p>',8)),(t(),r(A,null,{default:e(()=>[o(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E9%83%A8%E7%BD%B2%E7%9A%84%E9%87%8F%E5%8C%96%E7%9B%AE%E6%A0%87%20p_q%22%5D%20--%3E%20M%5B%22%E5%9C%A8%20p_q%20%E4%B8%8A%E9%87%8D%E6%B5%8B%20%CE%B1%20%E4%B8%8E%20c%20%E6%AF%94%22%5D%0A%20%20D%5B%22%E9%87%8F%E5%8C%96%E8%8D%89%E7%A8%BF%20q_q%22%5D%20--%3E%20M%0A%20%20M%20--%3E%20DEC%7B%22%E6%A1%B6%E8%B4%A6%E4%BB%8D%E5%87%80%E8%B5%9A%3F%22%7D%0A%20%20DEC%20--%3E%7C%22%E6%98%AF%22%7C%20TUNE%5B%22%E9%87%8D%E8%B0%83%20%CE%B3%20%E4%B8%8E%E6%A0%91%E5%AE%BD%22%5D%0A%20%20DEC%20--%3E%7C%22%E5%90%A6%22%7C%20QOFF%5B%22%E9%99%8D%E8%8D%89%E7%A8%BF%E6%A1%A3%E4%BD%8D%E6%88%96%E5%85%B3%E6%8A%95%E6%9C%BA%22%5D%0A%20%20TUNE%20--%3E%20SHIP%5B%22%E5%A3%B0%E6%98%8E%EF%BC%9A%E6%97%A0%E6%8D%9F%E7%9B%B8%E5%AF%B9%20p_q%22%5D%0A%20%20QOFF%20--%3E%20SHIP%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"组合收益的机制可以拆成一个乘法和一个减法。乘法在分母的带宽上：每 token 摊到的权重读取次数，量化给系数（字节/token 减半），投机给次数（\\(\\tau\\) 个 token 摊一次读取），两者作用于不同因子，在带宽受限段近似相乘。减法在余量上：量化抬高算术强度，把工作点往算力屋顶推，投机的校验增量从「近免费」滑向「按 FLOPs 计价」——同一台机器上量化开得越狠，投机的最优 \\(\\gamma\\) 越小，极端时正确配置就是关掉。这解释了一个实践中反复出现的现象：全精度单测里赚 3 倍的组合，量化高并发部署后只剩一点几倍——不是谁做错了，是工作点换了段。正确性一侧则干净：接受规则只看部署的 \\(p\\) 与 \\(q\\)，量化只是改变了这两个分布是什么，「无损相对 \\(p_q\\)」的声明在数学上与全精度情形同构。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"fp8 目标上量化让校验前向的字节减半、时间约减半，\\(\\tau\\) 不变：绝对延迟直接便宜一半，加速比却几乎不动。汇报时把这两个数分开——加速比是相对量，用户等的是绝对毫秒。")],-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：bf16 的 8B 模型每步读约 16 GB 权重；fp8 量化后约 8 GB。若投机每轮前进 \\(\\tau=3\\)，量化与投机相乘，每 token 摊到 \\(8/3\\approx 2.7\\) GB——「字节减半」与「次数摊三」作用在不同因子上，这正是带宽受限段两者近似相乘的算术。")],-1)),(t(),r(A,null,{default:e(()=>[o(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%AF%8F%20token%20%E6%91%8A%E5%88%B0%E7%9A%84%E6%9D%83%E9%87%8D%E8%AF%BB%E5%8F%96%22%5D%20--%3E%20MU%5B%22%E4%B9%98%E6%B3%95%3A%20%E9%87%8F%E5%8C%96%E5%87%8F%E5%AD%97%E8%8A%82%20%C3%97%20%E6%8A%95%E6%9C%BA%E6%91%8A%E6%AC%A1%E6%95%B0%22%5D%0A%20%20W%20--%3E%20SU%5B%22%E5%87%8F%E6%B3%95%3A%20%E9%87%8F%E5%8C%96%E6%8A%AC%E7%AE%97%E6%9C%AF%E5%BC%BA%E5%BA%A6%2C%20%E4%BD%99%E9%87%8F%E8%A2%AB%E5%90%83%22%5D%0A%20%20MU%20--%3E%20G%5B%22%E5%B8%A6%E5%AE%BD%E5%8F%97%E9%99%90%E6%AE%B5%3A%20%E4%B8%A4%E6%9D%A0%E6%9D%86%E6%94%B6%E7%9B%8A%E8%BF%91%E4%BC%BC%E7%9B%B8%E4%B9%98%22%5D%0A%20%20SU%20--%3E%20B%5B%22%E5%B7%A5%E4%BD%9C%E7%82%B9%E6%BB%91%E5%90%91%E7%AE%97%E5%8A%9B%E5%B1%8B%E9%A1%B6%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%A0%A1%E9%AA%8C%E4%BB%8E%E8%BF%91%E5%85%8D%E8%B4%B9%E6%BB%91%E5%90%91%E6%8C%89%20FLOPs%20%E8%AE%A1%E4%BB%B7%22%5D%0A%20%20C%20--%3E%20R%5B%22%E9%87%8F%E5%8C%96%E8%B6%8A%E7%8B%A0%2C%20%E6%8A%95%E6%9C%BA%E6%9C%80%E4%BC%98%20%CE%B3%20%E8%B6%8A%E5%B0%8F%2C%20%E6%9E%81%E7%AB%AF%E5%88%99%E5%85%B3%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>草稿量化下探有底线：\\(\\alpha\\) 曲线的拐点因草稿家族而异，自投机头与目标共享表示，量化目标本身已经动过特征，草稿侧再加量化是双重扰动，要单独测。混合精度会改变逐层敏感度的排序，投机校验对个别高敏感层的误差放大更敏感，逐层方案见 <a href="/llm/hessian-aware-quant">Hessian 感知量化</a>。端侧场景两层叠加最狠（4-bit 目标 + 复制草稿），但那里本来余量结构就不同，见<a href="/llm/spec-edge">边缘端的投机</a>。最后，口径纪律留给下一课：本课只立一条——任何组合数字必须同时报量化档、批量与温度，缺一项就是不可比。</p><p><span class="marginnote">常见误区：以为两个杠杆都开了收益一定叠加。乘法只在带宽受限段成立；工作点被量化推近算力屋顶后，两者就从「相乘」变成「互抢」，极端配置下正确做法是把投机关掉。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无损的参照系是部署中的量化目标：声明写成「无损相对 \\(p_q\\)」，bf16 表不外推。</li><li>灵敏度不对称：目标量化对质量线负责，草稿量化只对 \\(\\alpha\\) 曲线负责，可以压得更狠。</li><li>乘法与减法并存：带宽受限段两杠杆近似相乘；量化抬高算术强度，侵蚀投机赖以赚钱的余量。</li><li>KV 量化同步砍校验带宽；「短而宽」的校验形状不能退化成逐 token 调用。</li><li>\\(\\gamma\\)、树宽、成本比在量化部署上全部重调，以实测为准。</li><li>出处：Leviathan et al., ICML 2023；Chen et al., 2023；量化口径据本仓库量化课序综合。</li></ul>',5))])}const _=i(d,[["render",m]]);export{F as __pageData,_ as default};
